export function listarInscricoes({ participanteId, ehOrganizacao, atividadeId }) {
  let resultado = inscricoesStore;
  if (!ehOrganizacao) resultado = resultado.filter((i) => i.participanteId === participanteId);
  if (atividadeId) resultado = resultado.filter((i) => i.atividadeId === atividadeId);
