parts.text:
Now update renderizarAtividades to add action buttons per card, and update init to call recarregar. Also after org form success it calls carregarAtividades — could switch to recarregar (harmless). Modal actions call carregarAtividades — fine.

renderizarAtividades: find user's inscription for atv:

```js
const minha = minhasInscricoes.find(i => i.atividadeId === atv.id && STATUS_ATIVOS.includes(i.status));
```

Also include cancelled/expired for re-inscrever: if user has any inscription in cancelada/expirada only → show Inscrever. Since API allows re-inscription, compute active only; if none active → Inscrever button (even if historical cancelada exists).

Buttons HTML in card footer area:

```js
const acoesHtml = ehOrganizacao() ? '' : (() => {
  const ativa = minhasInscricoes.find(i => i.atividadeId === atv.id && STATUS_ATIVOS.includes(i.status));
  if (!ativa) return `<button class="btn primary btn-mini btn-inscrever" data-atv="${atv.id}">Inscrever</button>`;
  let b = `<button class="btn secondary btn-mini btn-cancelar" data-insc="${ativa.id}">Cancelar</button>`;
  if (ativa.status === 'convocada') b = `<button class="btn primary btn-mini btn-confirmar" data-insc="${ativa.id}">Confirmar</button> ` + b;
  return b;
})();
```

And status badge on card if ativa: show `<span class="badge status-${ativa.status}">`.

Add to card HTML + wire listeners with stopPropagation.

input.newString:
function renderizarAtividades(atividades) {
  if (atividades.length === 0) {
    atividadesGrid.innerHTML = '<p>Nenhuma atividade encontrada.</p>';
    return;
  }

  atividadesGrid.innerHTML = '';
  atividades.forEach(atv => {
    const sala = salasMap[atv.salaId] ? salasMap[atv.salaId].nome : atv.salaId;
    const minhaAtiva = minhasInscricoes.find(
      (i) => i.atividadeId === atv.id && STATUS_ATIVOS.includes(i.status)
    );

    let acoesHtml = '';
    if (!ehOrganizacao()) {
      if (!minhaAtiva) {
        acoesHtml = `<button class="btn primary btn-mini btn-inscrever" data-atv="${atv.id}">Inscrever</button>`;
      } else {
        const btns = [];
        if (minhaAtiva.status === 'convocada') {
          btns.push(`<button class="btn primary btn-mini btn-confirmar" data-insc="${minhaAtiva.id}">Confirmar</button>`);
        }
        btns.push(`<button class="btn secondary btn-mini btn-cancelar" data-insc="${minhaAtiva.id}">Cancelar</button>`);
        acoesHtml = btns.join(' ');
      }
    }

    const card = document.createElement('div');
    card.className = 'atividade-card';
    card.innerHTML = `
      <div>
        <div class="atividade-header">
          <span class="atividade-titulo">${escapeHtml(atv.titulo)}</span>
          <span class="badge ${atv.tipo}">${atv.tipo}</span>
        </div>
        <div class="atividade-info">
          <span>📍 Sala: ${escapeHtml(sala)}</span>
          <span>⏱️ Carga Horária: ${atv.cargaHorariaMinutos} min</span>
          <span>👥 Vagas Restantes: ${atv.vagasRestantes} / ${atv.vagas}</span>
          ${minhaAtiva ? `<span>🎫 Minha inscrição: <span class="badge status-${minhaAtiva.status}">${minhaAtiva.status.replace('_', ' ')}</span></span>` : ''}
        </div>
      </div>
      <div class="atividade-footer">
        <span class="badge ${atv.situacao}">${atv.situacao.replace('_', ' ')}</span>
        <span class="atividade-acoes">
          ${acoesHtml}
          <span class="ver-detalhes" style="color: var(--primary);">Ver detalhes →</span>
        </span>
      </div>
    `;

    const btnInscrever = card.querySelector('.btn-inscrever');
    if (btnInscrever) {
      btnInscrever.addEventListener('click', (e) => {
        e.stopPropagation();
        inscreverAtividade(atv.id);
      });
    }
    const btnCancelar = card.querySelector('.btn-cancelar');
    if (btnCancelar) {
      btnCancelar.addEventListener('click', (e) => {
        e.stopPropagation();
        cancelarInscricao(minhaAtiva.id);
      });
    }
    const btnConfirmar = card.querySelector('.btn-confirmar');
    if (btnConfirmar) {
      btnConfirmar.addEventListener('click', (e) => {
        e.stopPropagation();
        confirmarInscricao(minhaAtiva.id);
      });
    }

    card.addEventListener('click', () => abrirDetalhesAtividade(atv.id));
    atividadesGrid.appendChild(card);
  });
}

