input.command:
node --input-type=module -e "
import { criarServidor } from './src/app.js';
const app = criarServidor();
const server = app.listen(0, async () => {
  const port = server.address().port;
  const html = await (await fetch('http://localhost:'+port+'/')).text();
  const js = await (await fetch('http://localhost:'+port+'/app.js')).text();
  const ok = html.includes('Minhas Inscrições') && js.includes('btn-inscrever') && js.includes('btn-cancelar') && js.includes('btn-confirmar') && js.includes('posicaoNaEspera');
  console.log(ok ? 'INTERFACE OK' : 'INTERFACE FALHOU');
  server.close();
  process.exit(ok ? 0 : 1);
});
"

