const VOID = new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);

class Elemento {
  constructor(tag, doc) {
    this.tagName = tag.toUpperCase();
    this.nodeName = this.tagName;
    this.ownerDocument = doc;
    this.childNodes = [];
    this.parentNode = null;
    this.attributes = new Map();
    this.listeners = new Map();
    this.textContent = '';
    this.value = '';
  }
  get children() { return this.childNodes.filter(n => n instanceof Elemento); }
  get firstChild() { return this.childNodes[0] || null; }
  get lastChild() { return this.childNodes[this.childNodes.length - 1] || null; }
  get className() { return this.attributes.get('class') || ''; }
  set className(v) { this.attributes.set('class', String(v)); }
  get id() { return this.attributes.get('id') || ''; }
  set id(v) { this.attributes.set('id', String(v)); }
  get classList() {
    const self = this;
    return {
      add(...cs) { const s = new Set(self.className.split(/\s+/).filter(Boolean)); cs.forEach(c => s.add(c)); self.className = [...s].join(' '); },
      remove(...cs) { const s = new Set(self.className.split(/\s+/).filter(Boolean)); cs.forEach(c => s.delete(c)); self.className = [...s].join(' '); },
      contains(c) { return self.className.split(/\s+/).filter(Boolean).includes(c); },
      toggle(c) { this.contains(c) ? this.remove(c) : this.add(c); }
    };
  }
  set innerHTML(html) { this.childNodes = []; ... parse tree with this as parent; this._innerHTML = String(html); }
  get innerHTML() { return this._innerHTML ?? ''; }
  setAttribute(k, v) / getAttribute(k) / hasAttribute(k)
  appendChild(node) { if (node.parentNode) remove; node.parentNode = this; this.childNodes.push(node); return node; }
