```js
function parsearHtml(html, pai, doc) {
  const texto = String(html).replace(/<!--[\s\S]*?-->/g, '');
  const re = /<(\/)?([a-zA-Z][a-zA-Z0-9]*)((?:"[^"]*"|'[^']*'|[^>"'])*)>/g;
  const pilha = [pai];
  let m;
  while ((m = re.exec(texto))) {
    const [_, fecha, tagBruto, resto] = m;
    const tag = tagBruto.toLowerCase();
    if (fecha) {
      for (let i = pilha.length - 1; i > 0; i--) {
        if (pilha[i].tagName.toLowerCase() === tag) { pilha.length = i; break; }
      }
      continue;
    }
    const el = new Elemento(tag, doc);
    // attrs
    const attrRe = /([^\s=\/]+)(?:\s*=\s*"([^"]*)")?/g;
    let a; const corpo = resto.trim();
    while ((a = attrRe.exec(corpo))) {
      if (!a[1] || a[1] === '/') continue;
      el.attributes.set(a[1], a[2] ?? '');
    }
    const atual = pilha[pilha.length - 1];
    el.parentNode = atual;
    atual.childNodes.push(el);
    if (!VOID.has(tag) && !corpo.endsWith('/')) pilha.push(el);
  }
}
```

