export function criarFetch() {
  const chamadas = [];
  const rotas = [];
  function fetch(url, init = {}) {
    const metodo = (init.method || 'GET').toUpperCase();
    const caminho = String(url).split('?')[0];
    chamadas.push({ metodo, caminho, url: String(url), headers: init.headers, body: init.body });
    const rota = rotas.find(r => r.metodo === metodo && r.caminho === caminho);
    if (!rota) return Promise.reject(new Error(`rota não programada: ${metodo} ${caminho}`));
    const r = typeof rota.resposta === 'function' ? rota.resposta(chamadas.length) : rota.resposta;
    return Promise.resolve({
      ok: r.status >= 200 && r.status < 300,
      status: r.status,
      json: async () => r.corpo
    });
  }
  fetch.programar = (metodo, caminho, status, corpo) => rotas.push({ metodo, caminho, status, corpo });
  fetch.chamadas = chamadas;
  return fetch;
}
```

